const build = (prompt, seed, prefix, negative = NEGATIVE) => ({
  '1': { class_type: 'CheckpointLoaderSimple', inputs: { ckpt_name: CHECKPOINT } },
  '2': { class_type: 'CLIPTextEncode', inputs: { text: prompt, clip: ['1', 1] } },
  '3': { class_type: 'CLIPTextEncode', inputs: { text: negative, clip: ['1', 1] } },
  '4': { class_type: 'EmptyLatentImage', inputs: { width: SIZE, height: SIZE, batch_size: 1 } },
  '5': { class_type: 'KSampler',
         inputs: { seed, steps: STEPS, cfg: CFG, sampler_name: SAMPLER, scheduler: SCHEDULER,
                   denoise: 1.0, model: ['1', 0], positive: ['2', 0], negative: ['3', 0],
                   latent_image: ['4', 0] } },
  '6': { class_type: 'VAEDecode', inputs: { samples: ['5', 0], vae: ['1', 2] } },
  '7': { class_type: 'SaveImage', inputs: { filename_prefix: prefix, images: ['6', 0] } }
});

async function enqueue(workflow) {
  const res = await fetch(`${BASE}/prompt`, {
    method: 'POST', headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ prompt: workflow, client_id: 'pf2edc-token-' + Math.random().toString(36).slice(2, 8) })
  });
  if (!res.ok) throw new Error(`enqueue failed: ${res.status} ${await res.text()}`);
  return (await res.json()).prompt_id;
}

async function waitFor(promptId, { timeoutMs = 420_000 } = {}) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    const res = await fetch(`${BASE}/history/${promptId}`);
    if (res.ok) {
      const entry = (await res.json())[promptId];
      const images = Object.values(entry?.outputs ?? {}).flatMap((o) => o.images ?? []);
      if (images.length) return images[0];
      if (entry?.status?.status_str === 'error') throw new Error('generation failed');
    }
    await new Promise((r) => setTimeout(r, 2500));
  }
  throw new Error(`timed out after ${timeoutMs}ms`);
}

async function fetchImage({ filename, subfolder = '', type = 'output' }) {
  const url = `${BASE}/view?filename=${encodeURIComponent(filename)}`
    + `&subfolder=${encodeURIComponent(subfolder)}&type=${type}`;
  const res = await fetch(url);
  if (!res.ok) throw new Error(`fetch failed: ${res.status}`);
  return Buffer.from(await res.arrayBuffer());
}

/**
 * How much background an image has, as one number to reroll against.
 *
 * This measured the four corners until the oozes got past it three times over:
 * a canyon with black sky in the corners, then a white halo with the corners
 * still black. It now matches tools/check-token-art.mjs — a ring right round
 * the outside, and a penalty for pale pixels anywhere — so the generator stops
 * keeping images the checker will reject afterwards.
 */
function backgroundScore(path) {
  const py = join(root, '.venv/bin/python3');
  const script = `
from PIL import Image
import sys
import numpy as np
a = np.asarray(Image.open(sys.argv[1]).convert('L'), dtype=float)
h, w = a.shape
r = max(1, int(min(w, h) * 0.10))
ring = np.concatenate([a[:r,:].ravel(), a[-r:,:].ravel(), a[:,:r].ravel(), a[:,-r:].ravel()])
bright = (a > 200).mean() * 100
# A pale backdrop is worth as much as a bright edge; the worse fault wins.
print(max(ring.mean(), bright * 2.5))
`;
  try {
    return parseFloat(execFileSync(py, ['-c', script, path], { encoding: 'utf8' }).trim());
  } catch {
    return null;                       // no Pillow: accept whatever came back
  }
}

/** Store at token size, not generation size. */
function shrink(src, dest) {
  const py = join(root, '.venv/bin/python3');
  // A clean raw attempt is fully opaque, so the lossy RGB path (small files —
  // the whole reason this exists, see the size comment above) is a no-op
  // loss for it either way. But a salvaged attempt has real transparency
  // from make-bg-transparent.mjs worth keeping for Foundry's rendering
  // instead of flattening it to a solid black square — detected here rather
  // than threaded through as a parameter, so both call sites (ComfyUI and
  // Gemini) get the fix automatically. `exact=True` matches
  // make-bg-transparent.mjs's own care: lossless webp is otherwise free to
  // repaint a (0,0,0,0) pixel's RGB.
  const script = `
from PIL import Image
import sys
img = Image.open(sys.argv[1]).convert('RGBA')
has_alpha = img.getchannel('A').getextrema()[0] < 255
resized = img.resize((512, 512), Image.LANCZOS)
if has_alpha:
    resized.save(sys.argv[2], 'WEBP', lossless=True, method=6, exact=True)
else:
    resized.convert('RGB').save(sys.argv[2], 'WEBP', quality=88, method=6)
`;
  try { execFileSync(py, ['-c', script, src, dest]); }
  catch { writeFileSync(dest, readFileSync(src)); }   // no Pillow: keep the png bytes
}

const CLEAN_THRESHOLD = 45;      // stay under the checker's 50
const MAX_ATTEMPTS = 4;   // 1 try + 3 retries via ComfyUI; if none comes back clean, fall back to the OpenRouter model hierarchy (tools/image-fallback.mjs), or pass --no-fallback. Never use --backend=gemini (API credits exhausted 2026-10-01).

/**
 * Try to key out a failed attempt's background instead of throwing the
 * generation away outright. Many "background" failures are otherwise-good
 * art on a flat, uniform off-black backdrop (grey, white, a solid color) —
 * exactly what `make-bg-transparent.mjs`'s border-seeded flood-fill (plus
 * its enclosed-island pass) is built to clear, as opposed to a full
 * illustrated scene (moon, cityscape, water), which it can't help with.
 *
 * Root-caused on `black-dracolisk` (2026-09-26): SDXL lightens the
 * background for subjects whose own prompt describes a predominantly dark
 * palette, fighting the shared style prompt's explicit "black background"
 * instruction — a legibility bias, not noise, so more rerolls don't fix it,
 * but the flat-fill result it produces instead salvages cleanly.
 *
 * Operates on a backup so a salvage that doesn't actually help (or that the
 * fraction-cleared safety gate rejects as too small/too large — a sign the
 * flood-fill either found no real background or ate into the subject) never
 * makes the kept image worse than the raw generation.
 */
function trySalvage(path, currentScore) {
  const backup = readFileSync(path);
  let parsed;
  try {
    const out = execFileSync('node', [join(root, 'tools/make-bg-transparent.mjs'), path], { encoding: 'utf8' });
    const match = out.match(/\{.*\}/);
    parsed = match && JSON.parse(match[0]);
  } catch {
    parsed = null;
  }
  if (!parsed || parsed.fraction < 0.10 || parsed.fraction > 0.90) {
    writeFileSync(path, backup);
    return null;
  }
  const salvagedScore = backgroundScore(path);
  if (salvagedScore === null || currentScore !== null && salvagedScore >= currentScore) {
    writeFileSync(path, backup);
    return null;
  }
  return salvagedScore;
}

/** Same worktree-vs-main-checkout resolution as .env — see loadDotEnv(). */
function resolveGeminiSystemPrompt() {
  const candidates = [join(root, 'gemini-system-prompt.txt')];
  const mainRoot = mainCheckoutRoot();
  if (mainRoot && mainRoot !== root) candidates.push(join(mainRoot, 'gemini-system-prompt.txt'));
  for (const p of candidates) {
    if (existsSync(p)) return readFileSync(p, 'utf8').trim();
  }
  throw new Error(
    `gemini-system-prompt.txt not found (looked in: ${candidates.join(', ')})`
  );
}

/**
 * Single paid call per subject — no reroll-and-keep-best-of-4 like the
 * ComfyUI path, since each attempt here is billed. Gemini's hit rate on the
 * manual workflow has been near-100% first-try, so a reroll loop would
 * mostly just be spending money to confirm what one call already showed.
 */
async function geminiGenerateOne(subject, dest) {
  const apiKey = process.env.GEMINI_API_KEY;
  if (!apiKey) {
    throw new Error(
      'GEMINI_API_KEY not set — add it to .env (this worktree or the main checkout) to use --backend=gemini'
    );
  }
  const systemPrompt = resolveGeminiSystemPrompt();
  const model = process.env.GEMINI_IMAGE_MODEL || 'gemini-3.1-flash-lite-image';
  const res = await fetch('https://generativelanguage.googleapis.com/v1beta/interactions', {
    method: 'POST',
    headers: { 'x-goog-api-key': apiKey, 'content-type': 'application/json' },
    body: JSON.stringify({
      model,
      input: [{ type: 'text', text: `${systemPrompt}\n\n${promptFor(subject)}` }],
      response_format: { type: 'image', mime_type: 'image/jpeg', aspect_ratio: '1:1' }
    })
  });
  if (!res.ok) throw new Error(`gemini request failed: ${res.status} ${await res.text()}`);
  const body = await res.json();
  // The docs describe an SDK convenience property `interaction.output_image`
  // that isn't a literal field in the raw REST response — the actual image
  // lives in the last `model_output` step's content, confirmed against a
  // real API response (2026-09-26).
  let data;
  for (const step of body.steps ?? []) {
    for (const block of step.content ?? []) {
      if (block.type === 'image' && block.data) data = block.data;
    }
  }
  if (!data) throw new Error(`gemini response had no image data: ${JSON.stringify(body).slice(0, 500)}`);
  writeFileSync(dest, Buffer.from(data, 'base64'));
}

/** .env spells it OPEN_ROUTER_API_KEY; a shell-level OPENROUTER_API_KEY (used
 *  by other tools) must not shadow it, so the .env name wins. */
function openrouterKey() {
  return process.env.OPEN_ROUTER_API_KEY || process.env.OPENROUTER_API_KEY || null;
}

/**
 * OpenRouter image backend (#429): POST /api/v1/images (b64_json response).
 * Same prompt as the Gemini backend (shared system prompt + creature line).
 * One call per model, billed on the owner's key; the model hierarchy lives in
 * tools/image-fallback.mjs and openrouterGenerate() walks it.
 */
async function openrouterGenerateOne(subject, dest, model) {
  const apiKey = openrouterKey();
  if (!apiKey) {
    throw Object.assign(
      new Error('OPEN_ROUTER_API_KEY not set — add it to .env (this worktree or the main checkout) to use OpenRouter'),
      { fatal: true }
    );
  }
  const systemPrompt = resolveGeminiSystemPrompt();
  // Image-only models (Muse, Flux, Seedream, ...) are served by the dedicated
  // /images endpoint, not chat/completions.
  const res = await fetch('https://openrouter.ai/api/v1/images', {
    method: 'POST',
    headers: { authorization: `Bearer ${apiKey}`, 'content-type': 'application/json' },
    body: JSON.stringify({ model, prompt: `${systemPrompt}\n\n${promptFor(subject)}` })
  });
  if (!res.ok) throw new Error(`openrouter request failed: ${res.status} ${await res.text()}`);
  const body = await res.json();
  const b64 = body.data?.[0]?.b64_json;
  if (!b64) throw new Error(`openrouter response had no image: ${JSON.stringify(body).slice(0, 500)}`);
  if (body.usage?.cost != null) process.stdout.write(`(cost $${body.usage.cost}) `);
  const buf = Buffer.from(b64, 'base64');
  writeFileSync(dest, buf);
}

/** Try each OpenRouter model in order until one returns an image. */
async function openrouterGenerate(subject, dest, models) {
  const { model } = await runFallbackChain(
    models,
    (m) => openrouterGenerateOne(subject, dest, m),
    (m, err) => process.stdout.write(`\n${' '.repeat(10)} ${m} failed: ${String(err.message).slice(0, 140)}\n${' '.repeat(10)} `)
  );
  return model;
}

async function main() {
  const args = process.argv.slice(2);
  const force = args.includes('--force');
  // --no-fallback: never spend on OpenRouter when ComfyUI cannot produce a clean image.
  const comfyFallback = !args.includes('--no-fallback');
  const orModels = openrouterModels({ override: args.find((a) => a.startsWith('--model='))?.split('=')[1] ?? null });
  const reroll = parseInt(args.find((a) => a.startsWith('--reroll='))?.split('=')[1] ?? '0', 10);
  const explicitBackend = args.some((a) => a.startsWith('--backend='));
  const backend = args.find((a) => a.startsWith('--backend='))?.split('=')[1] ?? 'comfyui';
  const routingRules = JSON.parse(readFileSync(new URL('../data/token-art-routing.json', import.meta.url), 'utf8'));
  if (!['comfyui', 'gemini', 'openrouter'].includes(backend)) {
    throw new Error(`unknown --backend=${backend}; expected comfyui, gemini or openrouter`);
  }
  if (backend === 'gemini' && !process.env.GEMINI_API_KEY) {
    throw new Error(
      'GEMINI_API_KEY not set — add it to .env (this worktree or the main checkout) to use --backend=gemini'
    );
  }
  const only = args.filter((a) => !a.startsWith('--'));
  const wanted = ALL.filter((s) => (!only.length || only.includes(s.id)));
  for (const s of wanted) {
    const outDir = dirFor(s);
    mkdirSync(outDir, { recursive: true });
    const dest = join(outDir, `${s.file}.png`);
    const final = join(outDir, `${s.file}.webp`);
    if (existsSync(final) && !force) { console.log(`${s.id.padEnd(10)} exists, skipping`); continue; }
    // ENFORCED ROUTING: a creature in data/token-art-routing.json is a known
    // ComfyUI failure, so it never goes through ComfyUI. Only an explicit
    // --backend=comfyui overrides this.
    let be = backend;
    if (backend === 'comfyui' && !explicitBackend) {
      const route = routeFor(s.id.replace(/-/g, ' '), routingRules, s.id);
      if (route.backend !== 'comfyui') { be = route.backend; console.log(`${s.id.padEnd(10)} routed to ${be}: ${route.why}`); }
    }
    if (be === 'gemini' || be === 'openrouter') {
      process.stdout.write(`${s.id.padEnd(10)} ${be}… `);
      let usedModel = null;
      try {
        if (be === 'gemini') await geminiGenerateOne(s, dest);
        else {
          // Muse and Flux draw centaurs as a bust or a plain horse; Krea is the only model
          // that draws the fused full body (see docs/token-art-persistent-failures.md).
          const hybridModels = /centaur/.test(s.id) && !args.some((a) => a.startsWith('--model='))
            ? openrouterModels({ override: 'krea/krea-2-medium-turbo' }) : orModels;
          usedModel = await openrouterGenerate(s, dest, hybridModels);
        }
      } catch (err) {
        // Every OpenRouter model refused this prompt (provider content
        // filters are per-prompt): log it and move on rather than abandoning
        // the rest of the batch. A fatal error (no key) still aborts.
        if (be === 'openrouter' && !err.fatal) {
          console.log(`FAILED ${String(err.message).slice(0, 300)}`);
          continue;
        }
        throw err;
      }
      shrink(dest, final);
      unlinkSync(dest);
      console.log(`-> ${s.dir ?? 'assets/tokens'}/${s.file}.webp${usedModel ? ` (${usedModel})` : ''}`);
      continue;
    }
    const prompt = promptFor(s);
    // The same prompt produces a plain background on some rolls and a lit
    // interior on others, so this rerolls rather than accepting the first
    // answer. The seed is derived from the ancestry and the attempt, so a
    // rerun reproduces the same sequence.
    //
    // The reduce must take its modulo on every step, not just at the end:
    // for any id longer than ~10 characters, `a * 31 + c.charCodeAt(0)`
    // blows past Number.MAX_SAFE_INTEGER well before the loop finishes, so
    // the accumulator silently loses precision and the low-order digits
    // (including the entire `+ reroll * 104_729` term added afterward)
    // round away to nothing — `--reroll=N` looked like it worked but
    // produced the exact same seed, and thus the exact same image, as
    // reroll=0 for every multi-word creature id. Caught live during ITEM-18
    // level -1 batch 2 generation: a `--reroll=1` redo of
    // `halfling-street-watcher` reproduced all 4 of its original attempts'
    // background scores exactly.
    const base = ([...s.id].reduce((a, c) => (a * 31 + c.charCodeAt(0)) % 2_000_000_000, 7)
      + reroll * 104_729) % 2_000_000_000;
    let best = null;
    for (let attempt = 0; attempt < MAX_ATTEMPTS; attempt += 1) {
      process.stdout.write(`${s.id.padEnd(10)} attempt ${attempt + 1}… `);
      try {
        const id = await enqueue(build(prompt, (base + attempt * 7919) % 2_000_000_000,
                                       `pf2edc-token-${s.id}`, negativeFor(s)));
        writeFileSync(dest, await fetchImage(await waitFor(id)));
      } catch (err) {
        // A ComfyUI error (timeout behind someone else's job, server down) is a
        // failed attempt, not a crash: the fallback below takes over if every
        // attempt fails.
        console.log(`ComfyUI error: ${String(err.message).slice(0, 120)}`);
        continue;
      }
      let score = backgroundScore(dest);
      if (score === null) { console.log('(unmeasured) kept'); best = { score: 0 }; break; }
      if (score >= CLEAN_THRESHOLD) {
        const salvaged = trySalvage(dest, score);
        if (salvaged !== null) {
          console.log(`background ${score.toFixed(0)} -> salvaged ${salvaged.toFixed(0)}`);
          score = salvaged;
        } else {
          console.log(`background ${score.toFixed(0)}`);
        }
      } else {
        console.log(`background ${score.toFixed(0)}`);
      }
      if (!best || score < best.score) {
        best = { score, buf: null };
        writeFileSync(join(outDir, `.best-${s.file}.png`), readFileSync(dest));
      }
      if (score < CLEAN_THRESHOLD) break;
    }
    const bestPath = join(outDir, `.best-${s.file}.png`);
    // ComfyUI could not produce a clean image (every attempt over the
    // background threshold, or every attempt errored): fall back to the
    // OpenRouter model hierarchy (#429), unless --no-fallback or no key.
    if ((best === null || best.score >= CLEAN_THRESHOLD) && comfyFallback && openrouterKey()) {
      process.stdout.write(`${' '.repeat(10)} no clean ComfyUI image; trying OpenRouter… `);
      try {
        const model = await openrouterGenerate(s, dest, orModels);
        if (existsSync(bestPath)) unlinkSync(bestPath);
        shrink(dest, final);
        unlinkSync(dest);
        console.log(`-> ${s.dir ?? 'assets/tokens'}/${s.file}.webp (fallback ${model})`);
        continue;
      } catch (err) {
        console.log(`fallback failed (${String(err.message).slice(0, 200)}); keeping the best ComfyUI attempt`);
      }
    }
    if (!existsSync(bestPath) && !existsSync(dest)) {
      console.log(`${' '.repeat(10)} FAILED: no image produced`);
      continue;
    }
    // Keep the darkest of the attempts if none came back clean.
    if (existsSync(bestPath)) {
      writeFileSync(dest, readFileSync(bestPath));
      unlinkSync(bestPath);
    }
    const kept = backgroundScore(dest);
    // ComfyUI returns a 1024 png; a token is drawn at a couple of hundred
    // pixels, so it is stored at 512 as webp — 1.5 MB becomes about 50 KB.
    shrink(dest, final);
    unlinkSync(dest);
    console.log(`${' '.repeat(10)} kept background ${kept === null ? '?' : kept.toFixed(0)}`
      + ` -> ${s.dir ?? 'assets/tokens'}/${s.file}.webp`);
  }
}

if (import.meta.url === `file://${process.argv[1]}`) await main();
